+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limit = parseLimit(message.limit);
+  if ('valid' in limit) return limit;
+
+  const before = parseBefore(message.before);
+  if ('valid' in before) return before;
+
+  const frame: ListSessionsMessage = {type: 'list_sessions'};
+  if (limit.value !== undefined) frame.limit = limit.value;
+  if (before.value !== undefined) frame.before = before.value;
+  return {valid: true, data: frame};
+}
+
+function parseLimit(limit: unknown): ParsedField<number | undefined> {
+  if (limit === undefined) return {ok: true, value: undefined};
+  if (typeof limit !== 'number' || !Number.isInteger(limit)) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+  if (limit < 0) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+  return {ok: true, value: limit};
+}
+
+function parseBefore(before: unknown): ParsedField<ListSessionsMessage['before']> {
+  if (before === undefined) return {ok: true, value: undefined};
+  if (!isRecord(before)) {
+    return {valid: false, error: 'list_sessions before must be an object'};
+  }
+
+  if (typeof before.sessionId !== 'string') {
+    return {valid: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
+  }
+  if (before.sessionId.length < 1 || before.sessionId.length > MAX_SESSION_ID_LENGTH) {
+    return {valid: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
+  }
+
+  const {updatedAt} = before;
+  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
+    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
+  }
+  if (!Number.isFinite(new Date(updatedAt).getTime())) {
+    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
+  }
+
+  return {ok: true, value: {updatedAt, sessionId: before.sessionId}};
+}
+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === 'object' && value !== null;
+}
